// Build daily report
const candidates = $('Get Today Candidates').all().map(i => i.json);
const funnelStats = $('Get Funnel Stats').all().map(i => i.json);

const today = new Date();
const dateFormatted = today.toLocaleDateString('ru-RU', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric'
});

let report = `📊 *Ежедневный отчёт*\n`;
report += `📅 ${dateFormatted}\n\n`;

// Статистика за сегодня
report += `*Сегодня добавлено:* ${candidates.length} кандидат(ов)\n\n`;

// Группировка по статусам
const byStatus = {};
candidates.forEach(c => {
  if (!byStatus[c.status]) byStatus[c.status] = [];
  byStatus[c.status].push(c);
});

const statusEmoji = {
  'направлен': '📋',
  'собеседование': '🗣',
  'оформление': '📝',
  'работает': '✅',
  'отказ': '❌',
  'архив': '📦'
};

if (candidates.length > 0) {
  report += '*По статусам:*\n';
  for (const [status, list] of Object.entries(byStatus)) {
    const emoji = statusEmoji[status] || '•';
    report += `${emoji} ${status}: ${list.length}\n`;
  }
  report += '\n';
}

// Воронка за день
if (funnelStats.length > 0) {
  report += '*Воронка найма (сегодня):*\n';
  funnelStats.forEach(s => {
    const emoji = statusEmoji[s.status] || '•';
    const bar = '█'.repeat(Math.min(Math.round(s.percentage / 10), 10));
    report += `${emoji} ${s.status}: ${s.count} (${s.percentage}%)\n`;
  });
  report += '\n';
}

// Список добавленных кандидатов
if (candidates.length > 0) {
  report += '*Добавленные кандидаты:*\n\n';

  candidates.slice(0, 15).forEach((c, i) => {
    report += `${i + 1}. *${c.full_name}*\n`;
    report += `   📞 ${c.phone || 'не указан'}\n`;
    report += `   💼 ${c.position || '-'} | 📍 ${c.object_location || '-'}\n`;
    if (c.recruiter) {
      report += `   👤 @${c.recruiter}\n`;
    }
    report += '\n';
  });

  if (candidates.length > 15) {
    report += `\n_...и ещё ${candidates.length - 15} кандидат(ов)_\n`;
  }
} else {
  report += '_Сегодня кандидаты не добавлялись._\n';
}

// Кнопки для действий
const keyboard = {
  inline_keyboard: [
    [
      { text: '📊 Статистика воронки', callback_data: 'report_funnel' },
      { text: '👥 По рекрутерам', callback_data: 'report_recruiters' }
    ],
    [
      { text: '📥 Экспорт за сегодня', callback_data: 'export_candidates_today' }
    ]
  ]
};

return {
  json: {
    report,
    keyboard,
    candidatesCount: candidates.length
  }
};
